  "package_id": "peerwork-proposal-adoption",
  "version": "1.0.0",
  "name": "Peerwork Proposal and Adoption",
  "description": "Reusable proposal and independent-adoption component. Adoption requires an authenticated actor different from the author recorded from auth.actorId and an exact candidate reference equal to the pinned state reference. Role conflict declarations additionally constrain role grants but do not implement the authorship predicate.",
